// @ts-nocheck
/* eslint-disable */
/**
 * Login page engine. GENERATED by tools/sync-login.mjs from web/index.xhtml — do not edit; change the script and run `npm run login:sync`.
 *
 * The two scripts of the Java page, same behaviour line by line: the one in <h:head> that decides where the page goes on
 * arrival (`?auth=` = the session filter sent the user back -> clear the old flags and show the form) and the one at the end
 * of <h:body> (show / hide password, "forgot password" notice, login -> branches -> select-org against POST /login_proxy,
 * Enter key, busy overlay, the company step with its "back" link, the focus on the user name).
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-login.mjs):
 *   - the call to /login_proxy is env.post() (the HttpClient of the app: mock backend in dev, cookies, API log) and it returns
 *     the same { status, ok, data, raw } the Java fetch chain produced;
 *   - "go to the dashboard" is env.enter(): the SPA opens the session (GET /session) and routes to Home — in Java it was a
 *     page load (window.location.href); if it fails the page says so, because here the user is still on it;
 *   - arrival: "is this tab signed in" is asked of the session (env.signedIn) instead of the ts_login flag in sessionStorage
 *     (the flag is still written and cleared exactly as in Java);
 *   - document.getElementById is byId() on the component's own root, timers are cleared by the function startLogin() returns.
 */

export interface LoginReply {
  status: number;
  ok: boolean;
  /** the parsed JSON body; null when the body is empty / not JSON */
  data: any;
  /** the body as text */
  raw: string;
}

export interface LoginEnv {
  /** the element that holds the generated markup */
  root: ParentNode;
  /** POST <apiBase>/login_proxy with a JSON body ({username,password} | {action:'branches'} | {action:'select-org',org}) */
  post: (payload: object) => Promise<LoginReply>;
  /** login is complete: open the session and show the Home page. Rejects when that is not possible. */
  enter: () => Promise<unknown>;
}

export interface LoginEntryEnv {
  /** is there a live server session? */
  signedIn: () => boolean;
  /** leave the login page for Home */
  redirectHome: () => void;
}

/** What to do on arrival: 'show' the form, or 'redirect' (already signed in; env.redirectHome() has been called). */
export function loginEntry(env: LoginEntryEnv): 'show' | 'redirect' {
        try {
            // ★ ถูก SessionTokenFilter เด้งกลับมา (?auth=NO_TOKEN/TOKEN_EXPIRED) = session ฝั่ง server ตายแล้ว
            //   (เช่นหลัง deploy/restart Tomcat) → ล้าง flag login เก่าของ tab นี้ทิ้ง แล้วโชว์หน้า login เลย
            //   ห้าม auto-redirect ต่อ ไม่งั้นจะวนลูป index.face <-> /pages/* ค้างหน้าขาว
            if (window.location.search.indexOf("auth=") !== -1) {
                sessionStorage.removeItem("ts_login");
                sessionStorage.removeItem("ts_username");
                return 'show';
            }
            /* Java: the sessionStorage flag "ts_login" (written by goDashboard) says "this tab is signed in" ->
               window.location.replace(dashboard). The SPA asks the session itself: after a reload the flag can outlive the
               server session, and then flag + route guard would bounce between /login and the app. */
            if (env.signedIn()) {
                env.redirectHome();
                return 'redirect';
            }
        } catch (e) { /* ignore */ }
    return 'show';
}

export function startLogin(env: LoginEnv): () => void {
            var destroyed = false;
            var timers = [];
            function byId(id) { return env.root.querySelector('#' + id); }
            function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
                /* LOGIN_URL and DASHBOARD_URL of the Java page: the call is env.post(), the destination is env.enter() */

                var $username = byId("username");
                var $password = byId("password");
                var $btn      = byId("loginBtn");
                var $form     = byId("loginForm");
                var $alert    = byId("alertBox");
                var $overlay  = byId("overlay");
                var $toggle   = byId("togglePass");
                var $toggleI  = byId("togglePassIcon");
                var $forgot   = byId("forgotLink");
                /* ขั้นตอนเลือกบริษัท (auth API ใหม่ 13/08/2026) */
                var $orgStep  = byId("orgStep");
                var $orgSel   = byId("orgSelect");
                var $orgBtn   = byId("orgSubmitBtn");
                var $orgUser  = byId("orgUser");
                var $orgBack  = byId("orgBackLink");

                function showAlert(type, msg) {
                    $alert.className = "alert " + type;
                    $alert.textContent = msg;
                    $alert.style.display = "block";
                }
                function hideAlert() {
                    $alert.style.display = "none";
                    $alert.textContent = "";
                }
                function setBusy(busy) {
                    $btn.disabled = busy;
                    $overlay.classList.toggle("show", !!busy);
                }

                $toggle.addEventListener("click", function () {
                    var isPwd = $password.type === "password";
                    $password.type = isPwd ? "text" : "password";
                    $toggleI.className = isPwd ? "fa-solid fa-eye" : "fa-solid fa-eye-slash";
                });

                $forgot.addEventListener("click", function (e) {
                    e.preventDefault();
                    showAlert("error", "กรุณาติดต่อผู้ดูแลระบบเพื่อรีเซ็ตรหัสผ่าน");
                });

                /* ยิง POST JSON ไป /login_proxy — ใช้ร่วมกันทั้ง 3 ขั้นตอน (login / branches / select-org) */
                function post(payload) {
                    /* fetch(LOGIN_URL, { POST, JSON, credentials: "same-origin" }) -> { status, ok, data, raw } of the Java page */
                    return env.post(payload);
                }

                /* login สำเร็จสมบูรณ์แล้ว (ผ่านหรือไม่ผ่านขั้นเลือกบริษัทก็ตาม) -> เข้าหน้า Dashboard */
                function goDashboard(data, username) {
                    try {
                        sessionStorage.setItem("ts_login", JSON.stringify(data));
                        sessionStorage.setItem("ts_username", username);
                    } catch (e) { /* ignore storage errors */ }

                    showAlert("success", "เข้าสู่ระบบสำเร็จ กำลังเข้าสู่หน้า Dashboard...");
                    /* ★ 19/08: เลิกล้างโหมดสว่าง/มืดตอน login (เดิมมี localStorage.removeItem('app-theme') ตรงนี้
                       = "reset theme to light mode on every login") — ผู้ใช้ที่ตั้งโหมดมืดไว้ต้องมากดใหม่ทุกครั้ง
                       ที่ login ทั้งที่กติกา 24/07 บอกให้จำโหมดที่เลือกไว้ข้ามหน้า/ข้ามรอบ */
                    /* window.location.href = DASHBOARD_URL  ->  open the session and the Home page of the SPA; if that fails the
                       user is still on this page, so say so (the Java page left the document and never came back) */
                    Promise.resolve().then(function () { return env.enter(); }).catch(function (err) {
                        console.error(err);
                        showAlert("error", "ไม่สามารถเชื่อมต่อ Service ได้: " + (err && err.message ? err.message : err));
                        setBusy(false);
                        $orgBtn.disabled = !$orgSel.value;
                    });
                }

                function doLogin() {
                    hideAlert();

                    var username = ($username.value || "").trim();
                    var password = $password.value || "";

                    if (!username || !password) {
                        showAlert("error", "กรุณาระบุ Username และ Password");
                        return;
                    }

                    setBusy(true);

                    post({ username: username, password: password })
                    .then(function (resp) {
                        if (!resp.ok) {
                            var serverMsg = resp.data && (resp.data.failMessage || resp.data.responseMessage);
                            showAlert("error", serverMsg || ("เข้าสู่ระบบไม่สำเร็จ (HTTP " + resp.status + ")"));
                            setBusy(false);
                            return;
                        }

                        var data = resp.data || {};
                        if (data.responseCode === "COMPLETE") {
                            goDashboard(data, username);
                        } else if (data.responseCode === "ORG_REQUIRED") {
                            /* บัญชีนี้อยู่ได้หลายบริษัท -> ต้องเลือกก่อนถึงจะเข้าระบบได้ */
                            showOrgStep(username);
                        } else {
                            var failMsg = data.failMessage || data.responseMessage
                                       || ("เข้าสู่ระบบไม่สำเร็จ (" + (data.responseCode || "UNKNOWN") + ")");
                            showAlert("error", failMsg);
                            setBusy(false);
                        }
                    })
                    .catch(function (err) {
                        console.error(err);
                        showAlert("error", "ไม่สามารถเชื่อมต่อ Service ได้: " + (err && err.message ? err.message : err));
                        setBusy(false);
                    });
                }

                /* ── ขั้นตอนเลือกบริษัท ───────────────────────────────────────────── */
                var pendingUser = "";

                function showOrgStep(username) {
                    pendingUser = username;
                    hideAlert();
                    $orgUser.textContent = username;
                    $form.style.display = "none";
                    $forgot.style.display = "none";
                    $orgStep.classList.add("show");
                    $orgBack.style.display = "block";
                    loadBranches();
                }

                function backToLogin() {
                    $orgStep.classList.remove("show");
                    $orgBack.style.display = "none";
                    $form.style.display = "";
                    $forgot.style.display = "";
                    $orgSel.innerHTML = '<option value="">กำลังโหลดรายชื่อบริษัท...</option>';
                    $orgBtn.disabled = true;
                    $password.value = "";
                    hideAlert();
                    setBusy(false);
                    $username.focus();
                }

                function loadBranches() {
                    setBusy(true);
                    $orgBtn.disabled = true;
                    $orgSel.disabled = true;
                    $orgSel.innerHTML = '<option value="">กำลังโหลดรายชื่อบริษัท...</option>';

                    post({ action: "branches" })
                    .then(function (resp) {
                        setBusy(false);
                        $orgSel.disabled = false;
                        var data = resp.data || {};
                        if (!resp.ok || data.responseCode !== "COMPLETE") {
                            $orgSel.innerHTML = '<option value="">โหลดรายชื่อบริษัทไม่สำเร็จ</option>';
                            showAlert("error", data.failMessage || "โหลดรายชื่อบริษัทไม่สำเร็จ");
                            return;
                        }
                        var list = data.branches || [];
                        if (!list.length) {
                            $orgSel.innerHTML = '<option value="">ไม่พบบริษัทที่ใช้งานได้</option>';
                            showAlert("error", "บัญชีนี้ยังไม่ถูกผูกกับบริษัทใด กรุณาติดต่อผู้ดูแลระบบ");
                            return;
                        }
                        var html = '<option value="">-- กรุณาเลือกบริษัท --</option>';
                        for (var i = 0; i < list.length; i++) {
                            var b = list[i] || {};
                            var name = b.nameTh || b.name || b.code || ("#" + b.id);
                            var label = b.code ? (name + " (" + b.code + ")") : name;
                            html += '<option value="' + String(b.id) + '">' + esc(label) + '</option>';
                        }
                        $orgSel.innerHTML = html;
                    })
                    .catch(function (err) {
                        setBusy(false);
                        $orgSel.disabled = false;
                        console.error(err);
                        $orgSel.innerHTML = '<option value="">โหลดรายชื่อบริษัทไม่สำเร็จ</option>';
                        showAlert("error", "ไม่สามารถเชื่อมต่อ Service ได้: " + (err && err.message ? err.message : err));
                    });
                }

                function submitOrg() {
                    var org = $orgSel.value || "";
                    if (!org) {                       /* บังคับต้องเลือก */
                        showAlert("error", "กรุณาเลือกบริษัทก่อนเข้าสู่โปรแกรม");
                        $orgSel.focus();
                        return;
                    }
                    hideAlert();
                    setBusy(true);
                    $orgBtn.disabled = true;

                    post({ action: "select-org", org: org })
                    .then(function (resp) {
                        var data = resp.data || {};
                        if (resp.ok && data.responseCode === "COMPLETE") {
                            goDashboard(data, pendingUser);
                            return;
                        }
                        setBusy(false);
                        $orgBtn.disabled = false;
                        showAlert("error", data.failMessage || ("เลือกบริษัทไม่สำเร็จ (HTTP " + resp.status + ")"));
                        if (resp.status === 401) {    /* session หมดอายุ -> ให้ login ใหม่ */
                            tmo(backToLogin, 1500);
                        }
                    })
                    .catch(function (err) {
                        setBusy(false);
                        $orgBtn.disabled = false;
                        console.error(err);
                        showAlert("error", "ไม่สามารถเชื่อมต่อ Service ได้: " + (err && err.message ? err.message : err));
                    });
                }

                function esc(s) {
                    return String(s === null || s === undefined ? "" : s)
                            .replace(/&/g, "&amp;").replace(/"/g, "&quot;")
                            .replace(/</g, "&lt;").replace(/>/g, "&gt;");
                }

                $form.addEventListener("submit", function (e) {
                    e.preventDefault();
                    doLogin();
                });
                $btn.addEventListener("click", function (e) {
                    e.preventDefault();
                    doLogin();
                });
                [$username, $password].forEach(function (el) {
                    el.addEventListener("keydown", function (e) {
                        if (e.key === "Enter") {
                            e.preventDefault();
                            doLogin();
                        }
                    });
                });

                /* ── ขั้นตอนเลือกบริษัท ── */
                $orgSel.addEventListener("change", function () {
                    $orgBtn.disabled = !$orgSel.value;      /* บังคับเลือกก่อนถึงจะกดปุ่มได้ */
                    if ($orgSel.value) { hideAlert(); }
                });
                $orgSel.addEventListener("keydown", function (e) {
                    if (e.key === "Enter") { e.preventDefault(); submitOrg(); }
                });
                $orgBtn.addEventListener("click", function (e) { e.preventDefault(); submitOrg(); });
                $orgBack.addEventListener("click", function (e) { e.preventDefault(); backToLogin(); });

                tmo(function () { $username.focus(); }, 50);

            return function destroy() {
                destroyed = true;
                timers.splice(0).forEach(function (h) { clearTimeout(h); });
            };
}
